// Demonstrates filtering, mapping, reduction and grouping
import java.util.*;
import java.util.stream.*;

class StreamExample {
    public static void main(String[] args) {
        List<Integer> amounts = List.of(5000, 12000, 18000, 7000);

        int total = amounts.stream()
            .filter(amount -> amount > 10000)
            .mapToInt(Integer::intValue)
            .sum();

        Map<Boolean, List<Integer>> grouped = amounts.stream()
            .collect(Collectors.groupingBy(amount -> amount > 10000));

        List<Integer> doubled = amounts.stream()
            .map(amount -> amount * 2)
            .collect(Collectors.toList());

        System.out.println(total);
        System.out.println(grouped);
    }
}

// Demonstrates Optional operations and lazy defaults
import java.util.*;

class OptionalExample {
    static Optional<String> findUser(int id) {
        if (id == 101) return Optional.of("Alice");
        return Optional.empty();
    }

    public static void main(String[] args) {
        String name = findUser(101)
            .map(String::toUpperCase)
            .orElse("UNKNOWN");

        String result = findUser(999)
            .orElseGet(() -> "Guest");

        String email = findUser(101)
            .flatMap(user -> Optional.of(user + "@mail.com"))
            .orElseThrow();

        System.out.println(name);
        System.out.println(result);
    }
}

