ReentrantLock with tryLock and timeout

  ReentrantLock lock = new ReentrantLock(true);  // fair

  void transfer(Account from, Account to, long amt)
          throws InterruptedException {
      while (true) {
          if (from.lock.tryLock(100, TimeUnit.MILLISECONDS)) {
              try {
                  if (to.lock.tryLock(100, TimeUnit.MILLISECONDS)) {
                      try {
                          if (from.balance >= amt) {
                              from.balance -= amt;
                              to.balance   += amt;
                          }
                          return;
                      } finally { to.lock.unlock(); }
                  }
              } finally { from.lock.unlock(); }
          }
          // timeout: retry (avoids deadlock without lock ordering)
      }
  }

Conditions (producer-consumer)

  ReentrantLock lock = new ReentrantLock();
  Condition notFull  = lock.newCondition();
  Condition notEmpty = lock.newCondition();

  void put(T item) throws InterruptedException {
      lock.lock();
      try {
          while (queue.size() == capacity) notFull.await();
          queue.add(item);
          notEmpty.signal();
      } finally { lock.unlock(); }
  }

  T take() throws InterruptedException {
      lock.lock();
      try {
          while (queue.isEmpty()) notEmpty.await();
          T item = queue.remove();
          notFull.signal();
          return item;
      } finally { lock.unlock(); }
  }

ReadWriteLock

  ReadWriteLock rw = new ReentrantReadWriteLock();
  Lock r = rw.readLock();
  Lock w = rw.writeLock();

  V read(K key) {
      r.lock();
      try { return cache.get(key); }
      finally { r.unlock(); }
  }

  void write(K key, V val) {
      w.lock();
      try { cache.put(key, val); }
      finally { w.unlock(); }
  }

  // NO lock upgrade -- deadlock
  // r.lock(); w.lock();   <- illegal

  // Lock downgrade is allowed
  // w.lock(); r.lock(); w.unlock();   <- ok, still holding r

StampedLock optimistic read

  StampedLock sl = new StampedLock();
  double x, y;

  double distanceFromOrigin() {
      long stamp = sl.tryOptimisticRead();
      double cx = x, cy = y;              // read without locking
      if (!sl.validate(stamp)) {          // did a writer intervene?
          stamp = sl.readLock();          // fall back to a real read lock
          try { cx = x; cy = y; }
          finally { sl.unlockRead(stamp); }
      }
      return Math.sqrt(cx*cx + cy*cy);
  }

  void move(double dx, double dy) {
      long stamp = sl.writeLock();
      try { x += dx; y += dy; }
      finally { sl.unlockWrite(stamp); }
  }

Deadlock avoidance (lock ordering)

  // BAD: different order -> deadlock
  // T1: lock A then B    T2: lock B then A

  // GOOD: global ordering (by account id)
  if (from.id < to.id) {
      from.lock.lock(); to.lock.lock();
  } else {
      to.lock.lock(); from.lock.lock();
  }
  try { /* transfer */ }
  finally {
      if (from.id < to.id) { to.lock.unlock(); from.lock.unlock(); }
      else                 { from.lock.unlock(); to.lock.unlock(); }
  }

Diagnose with jstack

  jstack <pid> | grep -A 30 'Found one Java-level deadlock'

CAS loop (what every atomic does internally)

  // pseudocode for AtomicInteger.incrementAndGet()
  while (true) {
      int current = value;         // read
      int next    = current + 1;   // compute
      if (compareAndSet(current, next))  // CAS
          return next;             // success
      // CAS failed -> someone else changed value -> retry
  }

AtomicInteger

  AtomicInteger count = new AtomicInteger();
  count.incrementAndGet();                 // atomic ++count
  int prev = count.getAndIncrement();      // atomic count++ (returns old)
  count.compareAndSet(5, 10);              // set to 10 only if current == 5
  count.updateAndGet(v -> v * 2);          // side-effect-free lambda

  // TRAP: side-effecting lambda runs on every retry
  // count.updateAndGet(v -> { log.info("x"); return v + 1; });  // logs multiple times

LongAdder (striped, high contention)

  LongAdder hits = new LongAdder();
  hits.increment();          // thread updates its own cell (no contention)
  long total = hits.sum();   // fuzzy: may include concurrent increments

  // vs AtomicLong under N threads:
  //   AtomicLong   -- all threads CAS the same field -> spins
  //   LongAdder    -- each thread updates its own cell -> linear scaling

ABA problem

  // Thread 1
  Node top = head.get();          // top = A
  Node next = top.next;            // next = B

  // Thread 2 (in between)
  // pop A, pop B, push A back with A.next = C

  // Thread 1
  head.compareAndSet(top, next);  // top == A still true -> SUCCEEDS
                                  // head now points to B (stale!) -> corruption

AtomicStampedReference (fix)

  AtomicStampedReference<Node> head = new AtomicStampedReference<>(A, 0);

  Node top = head.getReference();
  int stamp = head.getStamp();
  // ... compute next ...
  head.compareAndSet(top, next, stamp, stamp + 1);
  // succeeds only if BOTH value AND stamp are unchanged
  // any A->B->A transition increments the stamp, so CAS fails correctly

False sharing

  // BAD: both counters likely land on the same cache line
  class Counters {
      volatile long a;   // 64-byte line holds a AND b
      volatile long b;
  }
  // Thread A writes a -> invalidates the line on thread B's core
  // Thread B writes b -> invalidates the line on thread A's core
  // throughput drops even though no logical sharing exists

  // GOOD: pad to 64 bytes
  class Counters {
      volatile long a;
      long p1, p2, p3, p4, p5, p6, p7;   // padding
      volatile long b;
      long q1, q2, q3, q4, q5, q6, q7;
  }

  // Or on Java 8+ with the JVM flag:
  //   -XX:-RestrictContended
  @jdk.internal.vm.annotation.Contended
  volatile long a;

Decision guide

  single counter, exact value, low-medium contention   -> AtomicLong
  single counter, approximate, high contention         -> LongAdder
  ABA concern (lock-free with node reuse)              -> AtomicStampedReference
  multi-variable invariant                             -> lock, not atomics

ConcurrentHashMap -- atomic compound operations

  ConcurrentHashMap<String, List<Order>> byCustomer = new ConcurrentHashMap<>();

  // BAD: get-then-put is a race
  List<Order> list = byCustomer.get(custId);
  if (list == null) { list = new ArrayList<>(); byCustomer.put(custId, list); }
  list.add(order);    // list itself is not thread-safe either

  // GOOD: computeIfAbsent is atomic per bucket
  byCustomer.computeIfAbsent(custId, k -> new CopyOnWriteArrayList<>())
            .add(order);

  // Merge pattern for counters
  byCustomer.merge(custId, amount, Long::sum);   // atomic add

CopyOnWriteArrayList

  CopyOnWriteArrayList<Listener> listeners = new CopyOnWriteArrayList<>();

  // every add/remove copies the whole array
  listeners.add(newListener);

  // iteration is snapshot-safe, no ConcurrentModificationException
  for (Listener l : listeners) l.onEvent(e);   // safe even if listeners change

