BlockingQueue variants

  ArrayBlockingQueue (bounded, FIFO, backpressure)
    BlockingQueue<Task> q = new ArrayBlockingQueue<>(1000);
    q.put(task);       // blocks when full
    Task t = q.take(); // blocks when empty

  LinkedBlockingQueue (unbounded default -- TRAP)
    BlockingQueue<Task> q = new LinkedBlockingQueue<>();  // Integer.MAX_VALUE
    // hidden overload -> memory grows -> OOM
    BlockingQueue<Task> safe = new LinkedBlockingQueue<>(1000);  // bounded

  SynchronousQueue (no capacity, direct handoff)
    BlockingQueue<Task> q = new SynchronousQueue<>();
    // put blocks until a take arrives, and vice versa
    // used by Executors.newCachedThreadPool

  PriorityBlockingQueue
    BlockingQueue<Task> q = new PriorityBlockingQueue<>();
    // ordered by Comparator or Comparable; unbounded
    // take() always returns the highest-priority available

  DelayQueue
    DelayQueue<Retry> q = new DelayQueue<>();
    q.put(new Retry(task, Duration.ofSeconds(5)));
    Retry r = q.take();   // blocks until delay elapsed

  LinkedTransferQueue
    TransferQueue<Task> q = new LinkedTransferQueue<>();
    q.transfer(task);   // blocks until consumer takes
    q.tryTransfer(task);// non-blocking handoff

Non-blocking queues

  ConcurrentLinkedQueue<Task> q = new ConcurrentLinkedQueue<>();
  q.offer(task);
  Task t = q.poll();   // returns null if empty (does not block)

  // lock-free; used in event loops, lock-free algorithms

Sorted concurrent collections

  ConcurrentSkipListMap<String, Order> index = new ConcurrentSkipListMap<>();
  index.put("order-100", o);
  NavigableMap<String, Order> range = index.subMap("order-100", "order-200");

