import java.lang.ref.*;
import java.util.WeakHashMap;

// Strong: normal object ownership
Object strong = new Object();

// Soft: always support rebuilding
var soft = new SoftReference<>(new Object());
Object cached = soft.get();
if (cached == null) cached = new Object();

// Weak: does not retain its referent
var weak = new WeakReference<>(new Object());
Object maybe = weak.get(); // Can be null

// WeakHashMap: value must not retain its key
var map = new WeakHashMap<Object, Object>();
Object key = new Object();
map.put(key, key); // Trap: strong value retains key

