-- Bank transfer wrapped in an atomic ACID transaction
BEGIN;

UPDATE accounts SET balance = balance - 100 WHERE id = 101 AND balance >= 100;
-- Application checks that 1 row was updated; if 0 rows, execute ROLLBACK;

UPDATE accounts SET balance = balance + 100 WHERE id = 202;

INSERT INTO ledger_entries (from_id, to_id, amount) VALUES (101, 202, 100);

COMMIT; -- WAL is flushed to disk before database confirms success

-- Preventing a Lost Update two ways
-- 1. Pessimistic Locking (blocks concurrent writers on row id=42)
BEGIN;
SELECT stock FROM inventory WHERE id = 42 FOR UPDATE;
UPDATE inventory SET stock = stock - 1 WHERE id = 42;
COMMIT;

-- 2. Optimistic Locking (no lock held; app retries if 0 rows updated)
UPDATE inventory
SET stock = stock - 1, version = version + 1
WHERE id = 42 AND version = 7;

