// Cache-Aside Pattern in Java
public Product getProduct(String productId) {
    String key = "product:" + productId;
    // 1. Check cache first
    Product cached = redis.get(key);
    if (cached != null) {
        return cached; // Cache Hit
    }
    // 2. Cache Miss -> query primary database
    Product fromDb = productRepository.findById(productId).orElseThrow();
    // 3. Populate cache with a 10-minute TTL
    redis.setex(key, Duration.ofMinutes(10), fromDb);
    return fromDb;
}

// Mitigating Stampede (Mutex) + Penetration (Null Sentinel) + Avalanche (Jitter)
public String getProfile(String userId) {
    String key = "profile:" + userId;
    String val = redis.get(key);
    if (val != null) return "NULL".equals(val) ? null : val;

    // Acquire short per-key lock so only 1 thread queries DB on miss
    if (redis.setNx("lock:" + key, "1", Duration.ofSeconds(3))) {
        try {
            String dbVal = userRepo.findRawProfile(userId);
            int jitter = ThreadLocalRandom.current().nextInt(0, 60);
            if (dbVal == null) {
                redis.setex(key, Duration.ofSeconds(30), "NULL"); // Prevent penetration
                return null;
            }
            redis.setex(key, Duration.ofSeconds(300 + jitter), dbVal); // Prevent avalanche
            return dbVal;
        } finally {
            redis.del("lock:" + key);
        }
    }
    sleepMillis(25);
    return getProfile(userId); // Retry reading populated cache
}

