// Abstract class -- owns the flow, delegates variation points
abstract class DataImporter {

    // Template method -- FINAL to protect the algorithm's structure
    public final ImportReport importFile(String path) {
        byte[] raw = read(path);
        try {
            List<Row> rows = parse(raw);
            List<Row> valid = validate(rows);
            int written = write(valid);
            onSuccess(written);          // hook -- optional
            return new ImportReport(rows.size(), written);
        } catch (Exception e) {
            onFailure(e);                // hook -- optional
            throw new ImportException(path, e);
        }
    }

    // Abstract -- subclasses MUST provide
    protected abstract List<Row> parse(byte[] raw);

    // Concrete -- shared implementation
    protected byte[] read(String path) { return Files.readAllBytes(Path.of(path)); }

    protected List<Row> validate(List<Row> rows) {
        return rows.stream().filter(Row::isValid).toList();
    }

    protected int write(List<Row> rows) {
        return repository.saveAll(rows);
    }

    // Hooks -- default no-op, subclasses MAY override
    protected void onSuccess(int count) { }
    protected void onFailure(Exception e) { }
}

class CsvImporter extends DataImporter {
    protected List<Row> parse(byte[] raw) { return parseCsv(raw); }
}

class JsonImporter extends DataImporter {
    protected List<Row> parse(byte[] raw) { return parseJson(raw); }
    protected void onSuccess(int count) { log.info("json imported {} rows", count); }
}

