// Iterator interface in Java
public interface Iterator<T> {
    boolean hasNext();
    T next();
    default void remove() { throw new UnsupportedOperationException(); }
}

// for-each is compiled into:
for (T x : collection) { ... }
// becomes:
for (Iterator<T> it = collection.iterator(); it.hasNext(); ) {
    T x = it.next();
    ...
}

// Custom collection with custom iterator
class Range implements Iterable<Integer> {
    private final int start, end;
    Range(int s, int e) { this.start = s; this.end = e; }

    public Iterator<Integer> iterator() {
        return new Iterator<>() {
            private int current = start;
            public boolean hasNext() { return current < end; }
            public Integer next()     { return current++; }
        };
    }
}

for (int i : new Range(0, 5)) System.out.print(i + " ");  // 0 1 2 3 4

// FAIL-FAST -- the classic bug
List<String> names = new ArrayList<>(List.of("alice", "bob", "carol"));
for (String n : names) {
    if (n.equals("bob")) names.remove(n);   // ConcurrentModificationException
}

// FIX 1 -- iterator.remove()
Iterator<String> it = names.iterator();
while (it.hasNext()) {
    if (it.next().equals("bob")) it.remove();
}

// FIX 2 -- removeIf (cleaner)
names.removeIf(n -> n.equals("bob"));

// FIX 3 -- snapshot (safe but creates a copy)
for (String n : new ArrayList<>(names)) {
    if (n.equals("bob")) names.remove(n);
}

// WEAKLY CONSISTENT -- CopyOnWriteArrayList
for (String n : new CopyOnWriteArrayList<>(names)) {
    // modifications during iteration do not throw, but may not be seen
}

// Stream -- the modern alternative
names.stream()
     .filter(n -> !n.equals("bob"))
     .forEach(System.out::println);

